Jaký bude výstup po vyčerpání prvků z instance `Odpocet`?

class Odpocet:
    def __init__(self, start):
        self.val = start
    def __iter__(self):
        return self
    def __next__(self):
        if self.val <= 0:
            raise StopIteration
        self.val -= 1
        return self.val + 1

it = Odpocet(2)
print(next(it), next(it))
try:
    print(next(it))
except StopIteration:
    print("Konec")

